export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) {
      throw new Error('Money amount must be a finite number');
    }

    if (amount < 0) {
      throw new Error('Money amount cannot be negative');
    }

    if (typeof currency !== 'string' || currency.trim().length === 0) {
      throw new Error('Money currency must be a non-empty string');
    }

    this.amount = amount;
    this.currency = currency.trim();
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (!(other instanceof Money)) {
      throw new Error('Can only add another Money value');
    }

    if (this.currency !== other.currency) {
      throw new Error(
        `Cannot add money with different currencies: ${this.currency} and ${other.currency}`
      );
    }

    return new Money(this.amount + other.amount, this.currency);
  }
}

export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

interface OrderItem {
  readonly itemId: string;
  quantity: number;
  readonly price: Money;
}

export interface OrderDomainEvent {
  readonly type: string;
  readonly orderId: string;
  readonly [key: string]: unknown;
}

export class Order {
  readonly id: string;
  readonly customerId: string;

  private currentStatus: OrderStatus;
  private readonly items: Map<string, OrderItem>;
  private readonly domainEvents: OrderDomainEvent[];

  constructor(id: string, customerId: string) {
    if (typeof id !== 'string' || id.trim().length === 0) {
      throw new Error('Order id must be a non-empty string');
    }

    if (typeof customerId !== 'string' || customerId.trim().length === 0) {
      throw new Error('Customer id must be a non-empty string');
    }

    this.id = id;
    this.customerId = customerId;
    this.currentStatus = 'PENDING';
    this.items = new Map<string, OrderItem>();
    this.domainEvents = [];
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  addItem(itemId: string, quantity: number, price: Money): void {
    if (this.currentStatus !== 'PENDING') {
      throw new Error('Items can only be added to a pending order');
    }

    if (typeof itemId !== 'string' || itemId.trim().length === 0) {
      throw new Error('Item id must be a non-empty string');
    }

    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('Item quantity must be a positive integer');
    }

    if (!(price instanceof Money)) {
      throw new Error('Item price must be a Money value');
    }

    const normalizedItemId = itemId.trim();
    const existingItem = this.items.get(normalizedItemId);

    if (existingItem) {
      existingItem.quantity += quantity;
    } else {
      this.items.set(normalizedItemId, {
        itemId: normalizedItemId,
        quantity,
        price
      });
    }

    this.recordEvent({
      type: 'OrderItemAdded',
      orderId: this.id,
      itemId: normalizedItemId,
      quantity,
      price
    });
  }

  pay(): void {
    if (this.currentStatus !== 'PENDING') {
      throw new Error('Only pending orders can be paid');
    }

    if (this.items.size === 0) {
      throw new Error('An order must contain at least one item before payment');
    }

    this.currentStatus = 'PAID';

    this.recordEvent({
      type: 'OrderPaid',
      orderId: this.id
    });
  }

  ship(): void {
    if (this.currentStatus !== 'PAID') {
      throw new Error('Only paid orders can be shipped');
    }

    this.currentStatus = 'SHIPPED';

    this.recordEvent({
      type: 'OrderShipped',
      orderId: this.id
    });
  }

  cancel(): void {
    if (this.currentStatus !== 'PENDING' && this.currentStatus !== 'PAID') {
      throw new Error('Only pending or paid orders can be cancelled');
    }

    this.currentStatus = 'CANCELLED';

    this.recordEvent({
      type: 'OrderCancelled',
      orderId: this.id
    });
  }

  getDomainEvents(): any[] {
    return this.domainEvents.slice();
  }

  private recordEvent(event: OrderDomainEvent): void {
    this.domainEvents.push(Object.freeze(event));
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

