export class Order {
  public readonly id: string;
  public readonly customerId: string;

  private _status: OrderStatus = 'PENDING';
  private readonly items: OrderItem[] = [];
  private readonly domainEvents: any[] = [];

  constructor(id: string, customerId: string) {
    if (typeof id !== 'string' || id.trim().length === 0) {
      throw new Error('Order id is required.');
    }

    if (
      typeof customerId !== 'string' ||
      customerId.trim().length === 0
    ) {
      throw new Error('Order customerId is required.');
    }

    this.id = id.trim();
    this.customerId = customerId.trim();
  }

  public get status(): OrderStatus {
    return this._status;
  }

  public addItem(itemId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error('Items can only be added to a pending order.');
    }

    if (typeof itemId !== 'string' || itemId.trim().length === 0) {
      throw new Error('Order item id is required.');
    }

    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('Order item quantity must be a positive integer.');
    }

    if (!(price instanceof Money)) {
      throw new Error('Order item price must be a Money value.');
    }

    this.items.push({
      itemId: itemId.trim(),
      quantity,
      price,
    });
  }

  public pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error(
        `An order can only be paid while pending. Current status: ${this._status}.`,
      );
    }

    if (this.items.length === 0) {
      throw new Error('An order must contain at least one item before payment.');
    }

    this._status = 'PAID';
    this.domainEvents.push(new OrderPaid(this.id, this.customerId));
  }

  public ship(): void {
    if (this._status !== 'PAID') {
      throw new Error(
        `An order can only be shipped after payment. Current status: ${this._status}.`,
      );
    }

    this._status = 'SHIPPED';
    this.domainEvents.push(new OrderShipped(this.id, this.customerId));
  }

  public cancel(): void {
    if (this._status !== 'PENDING' && this._status !== 'PAID') {
      throw new Error(
        `Only pending or paid orders can be cancelled. Current status: ${this._status}.`,
      );
    }

    this._status = 'CANCELLED';
    this.domainEvents.push(new OrderCancelled(this.id, this.customerId));
  }

  public getDomainEvents(): any[] {
    const events = [...this.domainEvents];
    this.domainEvents.length = 0;
    return events;
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}
